INSERT INTO public.screens (course_id, screen_number, screen_title, body, image_idea) VALUES
 ('bbbbbbb1-0000-4000-8000-000000000002',1,'Une eau qui lessive les continents',$b$Toute pluie qui tombe sur un continent finit par ruisseler, et en chemin elle attaque la roche. L'eau dissout patiemment des minéraux : du sodium, du chlore, du calcium, du magnésium. Les fleuves transportent ensuite ces éléments vers l'océan, en quantités minuscules à l'échelle d'une journée, mais considérables à l'échelle des millions d'années. Le sel que nous goûtons en nous baignant vient donc surtout de la terre ferme, pas de la mer elle-même. Chaque année, les cours d'eau du monde livrent plusieurs milliards de tonnes de matière dissoute. La mer, elle, ne rend presque rien : seule l'eau pure s'évapore, et les sels restent derrière, concentrés par le soleil.$b$,'Une rivière se jetant dans la mer, vue du ciel'),
 ('bbbbbbb1-0000-4000-8000-000000000002',2,'Pourquoi la salinité reste stable',$b$On pourrait croire que l'océan devient chaque année un peu plus salé. Ce n'est pas le cas : sa salinité tourne autour de trente-cinq grammes par litre depuis très longtemps. Des mécanismes retirent en effet du sel aussi vite qu'il en arrive. Les sources hydrothermales des dorsales captent une partie du magnésium, les organismes marins fixent du calcium dans leurs coquilles, et certains bassins isolés s'assèchent en laissant d'énormes dépôts de sel gemme. L'océan fonctionne donc comme un compte en banque à l'équilibre : les fleuves déposent, la géologie prélève. Les écarts locaux existent pourtant, et la mer Rouge ou la Baltique en donnent deux exemples opposés très parlants.$b$,'Coupe schématique d''une dorsale océanique'),
 ('bbbbbbb1-0000-4000-8000-000000000003',1,'Un réflexe universel',$b$Le bâillement traverse le règne animal. Les chiens bâillent, les poissons aussi, et le fœtus humain bâille déjà dans l'utérus, bien avant d'avoir la moindre notion de fatigue ou d'ennui. Ce simple constat suffit à écarter l'idée d'un comportement appris ou culturel. Il s'agit d'un réflexe ancien, inscrit très bas dans le cerveau, du côté du tronc cérébral. Un bâillement complet dure environ six secondes : la mâchoire s'ouvre largement, l'air entre profondément, les yeux se ferment, puis l'expiration se fait lentement. On peut le retarder mais difficilement l'empêcher, et le contrarier laisse souvent une sensation étrange d'inachevé, comme un éternuement interrompu en pleine course.$b$,'Un nourrisson en plein bâillement'),
 ('bbbbbbb1-0000-4000-8000-000000000003',2,'L''hypothèse de l''oxygène, abandonnée',$b$Pendant longtemps, l'explication tenait en une phrase : on bâille parce qu'on manque d'oxygène. L'idée est séduisante et fausse. Dans les années 1980, des expériences ont fait respirer aux volontaires des mélanges très riches en oxygène, puis très riches en gaz carbonique. La fréquence des bâillements n'a pas bougé de manière significative. Si le bâillement servait vraiment la respiration, ces conditions auraient dû le déclencher ou le supprimer. Le réflexe obéit donc à autre chose. Ce renversement est un bon exemple de la manière dont la science avance : une explication de bon sens, répétée pendant des décennies, cède devant une mesure simple mais bien conçue.$b$,'Un masque respiratoire de laboratoire'),
 ('bbbbbbb1-0000-4000-8000-000000000003',3,'Refroidir le cerveau',$b$L'hypothèse aujourd'hui la mieux soutenue est thermique. Le cerveau fonctionne dans une fenêtre de température étroite et supporte mal la surchauffe. En ouvrant grand la mâchoire, le bâillement augmente le flux sanguin dans le crâne et fait entrer un air plus frais par les voies nasales et buccales, ce qui rafraîchit le sang qui irrigue l'encéphale. Plusieurs études ont montré que l'on bâille davantage quand la température ambiante approche celle du corps, et nettement moins par grand froid. Appliquer une compresse froide sur le front réduit la fréquence des bâillements. Le réflexe ressemblerait donc à un ventilateur d'appoint, déclenché quand le cerveau chauffe un peu trop.$b$,'Une caméra thermique montrant un visage'),
 ('bbbbbbb1-0000-4000-8000-000000000003',4,'La contagion, affaire de lien social',$b$Voir quelqu'un bâiller suffit souvent à déclencher le même réflexe, et lire ce paragraphe y parviendra peut-être. Cette contagion n'a rien à voir avec la température : elle est sociale. Elle apparaît vers l'âge de quatre ou cinq ans, au moment où l'enfant devient capable de se représenter l'état mental d'autrui. Elle est plus forte entre proches qu'entre inconnus, et se vérifie aussi chez les chimpanzés et les chiens vivant auprès d'humains. Le bâillement contagieux fonctionnerait comme un signal discret de synchronisation du groupe, une manière silencieuse de dire que l'on partage le même état de vigilance et le même moment.$b$,'Deux amis bâillant en même temps'),
 ('bbbbbbb1-0000-4000-8000-000000000003',5,'Quand le bâillement inquiète',$b$Bâiller reste banal, mais son excès peut signaler un trouble. Des bâillements très fréquents accompagnent parfois l'apnée du sommeil, la migraine, la sclérose en plaques ou certains accidents vasculaires cérébraux. Des antidépresseurs en provoquent également. Les médecins parlent alors de bâillements pathologiques et cherchent la cause sous-jacente plutôt que le symptôme. À l'inverse, bâiller en réunion n'est pas nécessairement un signe d'ennui : c'est souvent le cerveau qui tente de rester vigilant dans une pièce trop chaude. Retenir un bâillement par politesse revient donc à empêcher une réponse physiologique utile. La prochaine fois, mieux vaut ouvrir la fenêtre que se forcer à garder la bouche fermée.$b$,'Une salle de réunion surchauffée'),
 ('bbbbbbb1-0000-4000-8000-000000000004',1,'Une activité nocturne intense',$b$Dormir n'est pas s'éteindre. Pendant la nuit, le cerveau traverse plusieurs cycles d'environ quatre-vingt-dix minutes, et à la fin de chacun surgit une phase singulière : le sommeil paradoxal. Le corps est alors presque totalement paralysé, mais les yeux s'agitent sous les paupières et l'activité électrique cérébrale ressemble à celle de l'éveil. C'est là que naissent les rêves les plus longs et les plus narratifs. Un adulte passe environ deux heures par nuit à rêver, soit près de six années au cours d'une vie entière. La plupart de ces récits s'effacent en quelques minutes au réveil, sauf si l'on se réveille en plein milieu de la scène.$b$,'Un tracé d''électroencéphalogramme nocturne'),
 ('bbbbbbb1-0000-4000-8000-000000000004',2,'Freud, puis les neurones',$b$Au début du vingtième siècle, Freud voyait dans le rêve la voie royale vers l'inconscient et un désir refoulé déguisé en images. L'idée a marqué la culture bien plus que la science. Dans les années 1970, des chercheurs ont proposé une explication inverse : pendant le sommeil paradoxal, le tronc cérébral envoie des signaux électriques désordonnés vers le cortex, qui fabrique après coup une histoire pour leur donner du sens. Le rêve serait alors un récit improvisé sur du bruit. Les travaux plus récents nuancent les deux positions : le contenu des rêves n'est ni purement aléatoire ni strictement symbolique, mais fortement lié aux préoccupations de la veille.$b$,'Un vieux divan de cabinet viennois'),
 ('bbbbbbb1-0000-4000-8000-000000000004',3,'Trier et consolider les souvenirs',$b$La fonction la mieux documentée du rêve concerne la mémoire. Pendant la nuit, l'hippocampe rejoue les séquences enregistrées dans la journée et les transfère vers le cortex, où elles deviennent des souvenirs durables. Des rats ayant parcouru un labyrinthe reproduisent pendant leur sommeil exactement les mêmes séquences de décharges neuronales. Chez l'humain, apprendre une tâche puis dormir améliore nettement la performance le lendemain, alors qu'une nuit blanche l'efface. Le rêve accompagnerait ce tri : garder l'utile, écarter le reste, relier le nouveau à l'ancien. Les émotions fortes seraient rejouées dans un contexte apaisé, ce qui expliquerait pourquoi une journée difficile se digère souvent mieux après une nuit complète.$b$,'Une carte de connexions neuronales'),
 ('bbbbbbb1-0000-4000-8000-000000000004',4,'Le simulateur de menaces',$b$Une autre piste fait du rêve un terrain d'entraînement. Les rêves négatifs sont bien plus fréquents que les rêves agréables : être poursuivi, tomber, arriver en retard, se retrouver démuni devant un public. Selon l'hypothèse dite de la simulation des menaces, le cerveau rejouerait sans risque des situations dangereuses pour préparer des réponses adaptées. Un rêve coûte beaucoup moins cher qu'une erreur réelle. Cette théorie explique bien la récurrence des cauchemars chez les enfants, dont le répertoire de dangers est encore en construction. Elle éclaire aussi les rêves d'examen, qui persistent longtemps après la fin des études, comme un exercice devenu inutile mais jamais désactivé.$b$,'Une silhouette courant dans un couloir sombre'),
 ('bbbbbbb1-0000-4000-8000-000000000004',5,'Se souvenir de ses rêves',$b$Certaines personnes affirment ne jamais rêver. En laboratoire, réveillées en plein sommeil paradoxal, elles racontent pourtant un rêve dans la grande majorité des cas. La différence tient au souvenir, pas à l'activité onirique. Les hormones de la mémoire fonctionnent au ralenti la nuit, et le contenu s'efface en quelques minutes si rien ne le fixe. Noter ses rêves au réveil, sans bouger et sans regarder son téléphone, augmente nettement le rappel en quelques jours. Les réveils multiples, fréquents chez les dormeurs légers, produisent le même effet. Rêver davantage n'est donc pas possible, mais se souvenir davantage l'est, et cela s'apprend en une semaine environ.$b$,'Un carnet posé sur une table de nuit');

INSERT INTO public.sources (course_id, claim, reference, page) VALUES
 ('bbbbbbb1-0000-4000-8000-000000000003','Les mélanges enrichis en oxygène ne modifient pas la fréquence des bâillements','Provine, R. R., Yawning as a stereotyped action pattern, Ethology, 1986','p. 109'),
 ('bbbbbbb1-0000-4000-8000-000000000004','Le rejeu hippocampique pendant le sommeil consolide la mémoire spatiale','Wilson & McNaughton, Science, 1994','p. 676');